<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';
function driver_current(): ?array {
 $id=(int)($_SESSION['driver_id']??0);
 if($id<1)return null;
 $q=db()->prepare('SELECT id,name,phone,avatar_path FROM delivery_drivers WHERE id=? AND active=1');$q->execute([$id]);
 return $q->fetch()?:null;
}
function driver_require(): array {
 $d=driver_current();if(!$d){header('Location: login.php');exit;}return $d;
}
function driver_coordinates($lat,$lng): ?array {
 if(!is_scalar($lat)||!is_scalar($lng)||!is_numeric($lat)||!is_numeric($lng))return null;
 $a=(float)$lat;$b=(float)$lng;
 return is_finite($a)&&is_finite($b)&&abs($a)<=90&&abs($b)<=180?[$a,$b]:null;
}
