nput:focus{outline:2px solid #62e1c2;border-color:#16ad85}.form-card button{width:100%;margin-top:14px}.status{font-size:13px;padding:12px 14px;background:#f2f6fa;border-radius:10px}.two-col{display:grid;grid-template-columns:1.15fr 1fr;gap:18px}.footer{background:var(--navy);color:#8b9ab0;display:flex;justify-content:space-between;padding:22px max(24px,calc((100vw - 1100px)/2));font-size:11px;letter-spacing:1px}.footer b{color:var(--mint)}@media(max-width:700px){.topbar-inner{align-items:flex-start;flex-direction:column}.nav{width:100%}.nav a{padding:9px 11px}.container{padding:24px 14px 35px}.two-col{grid-template-columns:1fr}.hero{padding:23px}.footer{padding:20px 15px}.card,article{padding:18px}}  .hero{background:linear-gradient(115deg,#8e3e18,#f09a54)}.hero .eyebrow{color:#fff0d8}.hero p{color:#fff4e9}.chip{background:#fff0df;color:#9b4c18}.order-id{color:#c46b23}.notice{background:#fff3e6;border-color:#f9c795;color:#854019}.order-elapsed{background:#fff4e7;color:#97521d} .btn,button{background:#ffb36d;color:#53280c}.btn:hover,button:hover{background:#ffa65b} .brand-icon{color:#ffb36d;border-color:#9c6643}.footer b{color:#ffb36d}.eyebrow{color:#cf6a20}input:focus{outline-color:#ffbd81;border-color:#e58d42}.profile-photo{width:78px;height:78px;object-fit:cover;border-radius:50%;border:3px solid #ffd7a5}.driver-profile-card{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.driver-profile-card h2{margin:0}.profile-placeholder{width:78px;height:78px;border-radius:50%;background:#ffe2c3;color:#8e431a;display:grid;place-items:center;font-size:30px;font-weight:800}.profile-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}@media(max-width:650px){.profile-fields{grid-template-columns:1fr}} </style><link rel=stylesheet href=/stockflow/motorizado/panel_v4.css?v=4></head><body>';
 echo '<header class="topbar"><div class="topbar-inner"><a class="brand" href="'.e(url('motorizado/index.php')).'"><span class="brand-icon">D</span><span><strong>Devioz Store</strong><small>PORTAL DE REPARTIDORES</small></span></a>';
 if ($logged) echo '<nav class="nav"><a class="'.($page==='index.php'?'selected':'').'" href="'.e(url('motorizado/index.php')).'">Mis pedidos</a><a class="'.(in_array($page,['historial.php','historial_detalle.php'],true)?'selected':'').'" href="'.e(url('motorizado/historial.php')).'">Mis entregas</a><a class="'.($page==='ubicacion.php'?'selected':'').'" href="'.e(url('motorizado/ubicacion.php')).'">Ubicación</a><a class="'.($page==='perfil.php'?'selected':'').'" href="'.e(url('motorizado/perfil.php')).'">Mi perfil</a><a class="signout" href="'.e(url('motorizado/logout.php')).'">Salir</a></nav>';
 echo '</div></header><main class="container"><div class="page-heading"><span class="eyebrow">DEVIOZ · DELIVERY</span><h1>'.e($title).'</h1><p>Gestiona tus entregas de forma rápida y segura.</p></div>';
}
function driver_page_end(): void {echo '</main><footer class="footer"><span>DEVIOZ STORE <b>·</b> REPARTOS</span><span>Tu ruta, tus entregas.</span></footer></body></html>';}
